  bool _editingFromDate; DateTime _displayedCalendarMonth; readonly ObservableCollection<AnalysisCameraCheckItem> _cameraChecks=new ObservableCollection<AnalysisCameraCheckItem>(); readonly ObservableCollection<AnalysisCameraCheckItem> _roiChecks=new ObservableCollection<AnalysisCameraCheckItem>(); readonly HashSet<string> _appliedCameraIds=new HashSet<string>(StringComparer.OrdinalIgnoreCase); readonly HashSet<string> _appliedRoiIds=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  public ObservableCollection<string> Labels {get;}=new ObservableCollection<string>(); public ChartValues<double> OnlineValues {get;}=new ChartValues<double>(); public ChartValues<double> OfflineValues {get;}=new ChartValues<double>(); public ChartValues<double> UptimeValues {get;}=new ChartValues<double>(); public SeriesCollection HealthSeries {get;} public Func<double,string> PercentFormatter {get;}=v=>v.ToString("0")+"%";
  public AnalysisPage_v3(){HealthSeries=new SeriesCollection {new ColumnSeries{Title="Trực tuyến",Values=OnlineValues,Fill=new SolidColorBrush(Color.FromRgb(39,201,109)),MaxColumnWidth=18,ColumnPadding=6},new ColumnSeries{Title="Ngoại tuyến",Values=OfflineValues,Fill=new SolidColorBrush(Color.FromRgb(255,112,133)),MaxColumnWidth=18,ColumnPadding=6},new LineSeries{Title="Hoạt động",Values=UptimeValues,Stroke=new SolidColorBrush(Color.FromRgb(54,123,255)),Fill=Brushes.Transparent,StrokeThickness=2.5,PointGeometry=DefaultGeometries.Circle,PointGeometrySize=6,ScalesYAt=1}};DataContext=this;InitializeComponent();var now=DateTime.Now;FromFilter.Value=now.Date;ToFilter.Value=now;RefreshDateFields();LoadCameraFilter();Loaded+=async(_,__)=>{await LoadRoiFilterAsync();await RefreshAsync();};Unloaded+=(_,__)=>_lifetime.Cancel();}
  void LoadCameraFilter(){var x=new List<AnalysisCameraOption>{new AnalysisCameraOption{Id="",Label="Tất cả camera"}};x.AddRange((GlobalSystem.Instance.CameraList??new List<Camera>()).Where(c=>c!=null&&!string.IsNullOrWhiteSpace(c.camID)).Select(c=>new AnalysisCameraOption{Id=c.camID.Trim(),Label=c.camID.Trim()}).GroupBy(c=>c.Id).Select(g=>g.First()).OrderBy(c=>c.Label));CameraFilter.ItemsSource=x;CameraFilter.SelectedIndex=0;_cameraChecks.Clear();_cameraChecks.Add(new AnalysisCameraCheckItem{Id="",Name="Tất cả camera",IsSelected=true});foreach(var item in x.Skip(1))_cameraChecks.Add(new AnalysisCameraCheckItem{Id=item.Id,Name=item.Label,IsSelected=true});CameraCheckList.ItemsSource=_cameraChecks;UpdateCameraFilterText();}
  void UpdateCameraFilterText(){var selected=_cameraChecks.Where(x=>x.Id!=""&&x.IsSelected).ToList();CameraFilterText.Text=selected.Count==_cameraChecks.Count-1||selected.Count==0?"Tất cả camera":selected.Count==1?selected[0].Name:selected.Count+" camera";CameraSelectedCountText.Text=selected.Count+"/"+Math.Max(0,_cameraChecks.Count-1);} void UpdateRoiFilterText(){var selected=_roiChecks.Where(x=>x.Id!=""&&x.IsSelected).ToList();RoiFilterText.Text=selected.Count==_roiChecks.Count-1||selected.Count==0?"Tất cả công đoạn":selected.Count==1?selected[0].Name:selected.Count+" công đoạn";RoiSelectedCountText.Text=selected.Count+"/"+Math.Max(0,_roiChecks.Count-1);}
  async Task LoadRoiFilterAsync(){try{var cameras=(GlobalSystem.Instance.CameraList??new List<Camera>()).Where(c=>c!=null&&!string.IsNullOrWhiteSpace(c.camID)&&(_appliedCameraIds.Count==0||_appliedCameraIds.Contains(c.camID))).ToList();var names=cameras.ToDictionary(c=>c.camID.Trim(),c=>string.IsNullOrWhiteSpace(c.name)?c.camID.Trim():c.name,StringComparer.OrdinalIgnoreCase);var response=await ApiManager.Instance.GetRoiBatchByCamerasAsync(cameras.Select(c=>c.camID),_lifetime.Token);var options=new List<AnalysisRoiOption>{new AnalysisRoiOption{Id="",Name="Tất cả công đoạn"}};options.AddRange((response?.Data??new List<ApiManager.RoiBatchItem>()).Where(row=>row!=null&&row.Roi!=null&&!string.IsNullOrWhiteSpace(row.CameraId)&&!string.IsNullOrWhiteSpace(row.Roi.Id??row.Roi.RoiId)).GroupBy(row=>row.CameraId.Trim()+"::"+(row.Roi.Id??row.Roi.RoiId).Trim(),StringComparer.OrdinalIgnoreCase).Select(g=>{var row=g.First();var roiId=row.Roi.Id??row.Roi.RoiId;var roiName=string.IsNullOrWhiteSpace(row.Roi.Name)?(string.IsNullOrWhiteSpace(row.Roi.RoiRule?.Name)?roiId:row.Roi.RoiRule.Name):row.Roi.Name;var cameraName=names.TryGetValue(row.CameraId.Trim(),out var name)?name:row.CameraId.Trim();return new AnalysisRoiOption{Id=roiId,Name=cameraName+" · "+roiName};}).OrderBy(r=>r.Name));RoiFilter.ItemsSource=options;RoiFilter.SelectedIndex=0;_roiChecks.Clear();foreach(var option in options)_roiChecks.Add(new AnalysisCameraCheckItem{Id=option.Id,Name=option.Name,IsSelected=true});RoiCheckList.ItemsSource=_roiChecks;UpdateRoiFilterText();}catch(OperationCanceledException){}catch(Exception ex){LoggerManager.LogException(ex,"Analysis.LoadRoiFilter");}}
  async Task RefreshAsync(){if(Interlocked.Exchange(ref _refreshing,1)!=0||_lifetime.IsCancellationRequested)return;try{var all=(GlobalSystem.Instance.CameraList??new List<Camera>()).Where(c=>c!=null&&!string.IsNullOrWhiteSpace(c.camID)).ToList();var chosen=CameraFilter.SelectedValue as string;var cameras=string.IsNullOrWhiteSpace(chosen)?all:all.Where(c=>string.Equals(c.camID,chosen,StringComparison.OrdinalIgnoreCase)).ToList();var ids=cameras.Select(c=>c.camID.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var bucket=((BucketFilter.SelectedItem as ComboBoxItem)?.Tag as string)??"1h";var now=DateTime.Now;var statuses=await ApiManager.Instance.GetPortalDeviceStatusBatchAsync(ids,_lifetime.Token)??new List<ApiManager.DeviceStatusResponse>();var trend=await ApiManager.Instance.GetCameraHealthTimeseriesAsync(now.Date,now,bucket,ids,_lifetime.Token);var states=statuses.Where(s=>s!=null&&!string.IsNullOrWhiteSpace(s.DeviceId)).GroupBy(s=>s.DeviceId,StringComparer.OrdinalIgnoreCase).ToDictionary(g=>g.Key,g=>g.Last().IsOnline==true,StringComparer.OrdinalIgnoreCase);var online=states.Count(s=>s.Value);var offline=Math.Max(0,ids.Count-online);var points=trend?.Data??new List<ApiManager.CameraHealthTimeseriesPoint>();var uptime=points.Any()?points.Average(p=>p.UptimePercent??0):(ids.Count==0?0:online*100d/ids.Count);TotalText.Text=ids.Count.ToString("N0");OnlineText.Text=online.ToString("N0");OfflineText.Text=offline.ToString("N0");UptimeText.Text=uptime.ToString("0.0")+"%";DisconnectText.Text=offline.ToString("N0");RangeText.Text=now.ToString("HH:mm dd/MM");UpdatedText.Text="Cập nhật: "+now.ToString("HH:mm:ss dd-MM");Labels.Clear();OnlineValues.Clear();OfflineValues.Clear();UptimeValues.Clear();foreach(var p in points.Skip(Math.Max(0,points.Count-24))){DateTime t;DateTime.TryParse(p.BucketStart,out t);Labels.Add((t==DateTime.MinValue?now:t).ToString("HH:mm"));OnlineValues.Add(p.Online);OfflineValues.Add(p.Unavailable>0?p.Unavailable:p.Offline+p.Unknown);UptimeValues.Add(p.UptimePercent??0);}if(!points.Any()){Labels.Add(now.ToString("HH:mm"));OnlineValues.Add(online);OfflineValues.Add(offline);UptimeValues.Add(uptime);}CameraGrid.ItemsSource=cameras.Select(c=>{var ok=states.TryGetValue(c.camID,out var v)&&v;return new AnalysisCameraRow{Status=ok?"● Trực tuyến":"● Ngoại tuyến",CameraId=c.camID,Name=string.IsNullOrWhiteSpace(c.name)?"—":c.name,Uptime=ok?"100%":"0%",Note=ok?"Hoạt động bình thường":"Cần kiểm tra kết nối"};}).ToList();CameraCountText.Text="Danh sách camera · "+ids.Count+" camera";}catch(OperationCanceledException){}catch(Exception ex){LoggerManager.LogException(ex,"Analysis.Refresh");}finally{Interlocked.Exchange(ref _refreshing,0);}}
  void CameraToggle_Click(object s,RoutedEventArgs e){CameraFilterPopup.IsOpen=!CameraFilterPopup.IsOpen;CameraFilterToggle.IsChecked=false;} void CameraSearchBox_TextChanged(object s,TextChangedEventArgs e){var q=CameraSearchBox.Text??"";CameraSearchHint.Visibility=string.IsNullOrWhiteSpace(q)?Visibility.Visible:Visibility.Collapsed;System.Windows.Data.CollectionViewSource.GetDefaultView(CameraCheckList.ItemsSource).Filter=item=>{var c=item as AnalysisCameraCheckItem;return c!=null&&(c.Id==""||c.Name.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0);};} void CameraCheckBox_Click(object s,RoutedEventArgs e){var item=(s as CheckBox)?.DataContext as AnalysisCameraCheckItem;if(item==null)return;if(item.Id==""){foreach(var c in _cameraChecks.Where(x=>x.Id!=""))c.IsSelected=item.IsSelected;}else{var all=_cameraChecks.First();all.IsSelected=_cameraChecks.Where(x=>x.Id!="").All(x=>x.IsSelected);}UpdateCameraFilterText();} void CameraResetBtn_Click(object s,RoutedEventArgs e){foreach(var c in _cameraChecks)c.IsSelected=true;CameraSearchBox.Text="";UpdateCameraFilterText();Keyboard.ClearFocus();} async void CameraApplyBtn_Click(object s,RoutedEventArgs e){_appliedCameraIds.Clear();foreach(var c in _cameraChecks.Where(x=>x.Id!=""&&x.IsSelected))_appliedCameraIds.Add(c.Id);CameraFilterPopup.IsOpen=false;UpdateCameraFilterText();Keyboard.ClearFocus();await LoadRoiFilterAsync();await RefreshAsync();}
  void RoiToggle_Click(object s,RoutedEventArgs e){RoiFilterPopup.IsOpen=!RoiFilterPopup.IsOpen;RoiFilterToggle.IsChecked=false;} void RoiSearchBox_TextChanged(object s,TextChangedEventArgs e){var q=RoiSearchBox.Text??"";System.Windows.Data.CollectionViewSource.GetDefaultView(RoiCheckList.ItemsSource).Filter=item=>{var r=item as AnalysisCameraCheckItem;return r!=null&&(r.Id==""||r.Name.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0);};} void RoiCheckBox_Click(object s,RoutedEventArgs e){var item=(s as CheckBox)?.DataContext as AnalysisCameraCheckItem;if(item==null)return;if(item.Id==""){foreach(var r in _roiChecks.Where(x=>x.Id!=""))r.IsSelected=item.IsSelected;}else _roiChecks.First().IsSelected=_roiChecks.Where(x=>x.Id!="").All(x=>x.IsSelected);UpdateRoiFilterText();} void RoiResetBtn_Click(object s,RoutedEventArgs e){foreach(var r in _roiChecks)r.IsSelected=true;RoiSearchBox.Text="";UpdateRoiFilterText();Keyboard.ClearFocus();} async void RoiApplyBtn_Click(object s,RoutedEventArgs e){_appliedRoiIds.Clear();foreach(var r in _roiChecks.Where(x=>x.Id!=""&&x.IsSelected))_appliedRoiIds.Add(r.Id);RoiFilterPopup.IsOpen=false;UpdateRoiFilterText();Keyboard.ClearFocus();await RefreshAsync();} async void ThresholdTimeText_KeyDown(object s,KeyEventArgs e){if(e.Key!=Key.Enter)return;TimeSpan value;if(!TimeSpan.TryParseExact(ThresholdTimeText.Text,"mm\\:ss",CultureInfo.InvariantCulture,out value)){ThresholdTimeText.Text="05:00";}await RefreshAsync();e.Handled=true;}
  void RefreshDateFields(){FromDateText.Text=(FromFilter.Value??DateTime.Now).ToString("dd/MM/yyyy HH:mm:ss",CultureInfo.InvariantCulture);ToDateText.Text=(ToFilter.Value??DateTime.Now).ToString("dd/MM/yyyy HH:mm:ss",CultureInfo.InvariantCulture);}
  void DateField_MouseLeftButtonDown(object s,MouseButtonEventArgs e){_editingFromDate=ReferenceEquals(s,FromDateField);var value=(_editingFromDate?FromFilter.Value:ToFilter.Value)??DateTime.Now;_displayedCalendarMonth=new DateTime(value.Year,value.Month,1);PopupTimeText.Text=value.ToString("HH:mm:ss",CultureInfo.InvariantCulture);DatePopup.PlacementTarget=(UIElement)s;RenderCalendar();DatePopup.IsOpen=true;e.Handled=true;}
  void CloseDatePopup_Click(object s,RoutedEventArgs e){DatePopup.IsOpen=false;}
  void PreviousMonth_Click(object s,RoutedEventArgs e){_displayedCalendarMonth=_displayedCalendarMonth.AddMonths(-1);RenderCalendar();}
  void NextMonth_Click(object s,RoutedEventArgs e){_displayedCalendarMonth=_displayedCalendarMonth.AddMonths(1);RenderCalendar();}
  void CalendarDay_Click(object s,RoutedEventArgs e){var button=s as Button;if(button==null||!(button.Tag is DateTime))return;TimeSpan time;if(!TimeSpan.TryParseExact(PopupTimeText.Text,"hh\\:mm\\:ss",CultureInfo.InvariantCulture,out time))time=TimeSpan.Zero;var value=((DateTime)button.Tag).Date.Add(time);if(_editingFromDate)FromFilter.Value=value;else ToFilter.Value=value;RefreshDateFields();RenderCalendar();}
  void RenderCalendar(){if(CalendarDaysPanel==null)return;CalendarMonthText.Text=_displayedCalendarMonth.ToString("MMMM yyyy",CultureInfo.InvariantCulture);CalendarDaysPanel.Children.Clear();var first=new DateTime(_displayedCalendarMonth.Year,_displayedCalendarMonth.Month,1);var start=first.AddDays(-(int)first.DayOfWeek);var selected=((_editingFromDate?FromFilter.Value:ToFilter.Value)??DateTime.Now).Date;for(var i=0;i<42;i++){var day=start.AddDays(i);var button=new Button{Content=day.Day.ToString(CultureInfo.InvariantCulture),Tag=day,Style=FindResource("AnalysisCalendarDay") as Style,Foreground=day.Month==_displayedCalendarMonth.Month?new SolidColorBrush(Color.FromRgb(220,235,250)):new SolidColorBrush(Color.FromRgb(110,140,160)),Opacity=day.Month==_displayedCalendarMonth.Month?1:0.45};if(day.Date==selected){button.Background=new SolidColorBrush(Color.FromRgb(36,107,232));button.BorderBrush=new SolidColorBrush(Color.FromRgb(36,107,232));}button.Click+=CalendarDay_Click;CalendarDaysPanel.Children.Add(button);}}
  void PopupTimeText_LostFocus(object s,RoutedEventArgs e){CommitPopupTime();} void PopupTimeText_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Enter){CommitPopupTime();e.Handled=true;}} void CommitPopupTime(){TimeSpan time;if(!TimeSpan.TryParseExact(PopupTimeText.Text,"hh\\:mm\\:ss",CultureInfo.InvariantCulture,out time))return;var current=(_editingFromDate?FromFilter.Value:ToFilter.Value)??DateTime.Now;if(_editingFromDate)FromFilter.Value=current.Date.Add(time);else ToFilter.Value=current.Date.Add(time);RefreshDateFields();}
  void Root_PreviewMouseDown(object s,MouseButtonEventArgs e){if(!DatePopup.IsOpen)return;var child=DatePopup.Child as UIElement;if((child!=null&&child.IsMouseOver)||FromDateField.IsMouseOver||ToDateField.IsMouseOver)return;DatePopup.IsOpen=false;}
  void FlashButton(Button button){var animation=new DoubleAnimation(0.55,1,new Duration(TimeSpan.FromMilliseconds(260)));button.BeginAnimation(OpacityProperty,animation);}
  async void Refresh_Click(object s,RoutedEventArgs e){FlashButton(s as Button);await RefreshAsync();} async void Filter_Changed(object s,SelectionChangedEventArgs e){if(s==CameraFilter&&IsLoaded)await LoadRoiFilterAsync();if(IsLoaded)await RefreshAsync();} async void Filter_DateChanged(object s,RoutedPropertyChangedEventArgs<object> e){RefreshDateFields();if(IsLoaded)await RefreshAsync();} async void Reset_Click(object s,RoutedEventArgs e){FlashButton(s as Button);var now=DateTime.Now;FromFilter.Value=now.Date;ToFilter.Value=now;RefreshDateFields();CameraFilter.SelectedIndex=0;BucketFilter.SelectedIndex=0;ThresholdTimeText.Text="10:00";await LoadRoiFilterAsync();await RefreshAsync();}
